function scheduleHero(){clearTimeout(heroTimer);if(state.route!=='home'||state.heroPaused||document.hidden)return;heroTimer=setTimeout(()=>{const el=$('#hero-carousel');if(el&&state.route==='home'&&!state.heroPaused&&!document.hidden){const rect=el.getBoundingClientRect();if(!el.contains(document.activeElement)&&!el.matches(':hover')&&rect.bottom>0&&rect.top<innerHeight)selectHero(state.heroSlide+1,false);else scheduleHero();}},5000);}
function selectHero(i){const el=$('#hero-carousel');if(!el)return;state.heroSlide=(i+heroSlides.length)%heroSlides.length;el.querySelectorAll('[data-hero-panel]').forEach((panel,k)=>{const active=k===state.heroSlide;panel.hidden=!active;panel.inert=!active;panel.setAttribute('aria-hidden',String(!active));});el.querySelectorAll('[data-hero-slide]').forEach((b,k)=>{b.classList.toggle('active',k===state.heroSlide);b.setAttribute('aria-pressed',String(k===state.heroSlide))});el.querySelector('.hero-prev').dataset.heroEdge=String((state.heroSlide+2)%3);el.querySelector('.hero-next').dataset.heroEdge=String((state.heroSlide+1)%3);scheduleHero();}
