const normalizeSearch=x=>String(x??'').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').toLowerCase().trim();
function eligible(ignoreLocation=false){
 if(state.country!=='السعودية')return[];
 const allowed=ignoreLocation||state.region==='كل المناطق'?null:(locationMap[state.country][state.region]||[]);
 const words=normalizeSearch(state.term).split(/\s+/).filter(Boolean);
 return items.filter(x=>(!allowed||(x.local?x.region===state.region:allowed.includes(x.city)))&&(ignoreLocation||state.city==='كل المدن'||x.city===state.city)&&(state.filter==='الكل'||x.section===state.filter)&&(!state.onlyMine||x.local)&&(state.priceMin===''||x.price>=Number(state.priceMin))&&(state.priceMax===''||x.price<=Number(state.priceMax))&&words.every(w=>{const hay=normalizeSearch([x.title,x.city,x.region,x.section,x.note].join(' ')),groups=[['جوال','جوالات','هاتف','هواتف','موبايل','ايفون'],['سياره','سيارات','سياره','مركبه','مركبات'],['لابتوب','حاسوب','كمبيوتر','لابتوبات','حاسبات'],['كنب','اريكه','ارائك','اثاث','اثات']];const terms=groups.find(g=>g.includes(w))||[w];return terms.some(t=>hay.includes(t))})).sort((a,b)=>Number(Boolean(b.local))-Number(Boolean(a.local))||(a.local&&b.local?items.indexOf(b)-items.indexOf(a):0));
}
