const filters=()=>'<div class="filter-bar" aria-label="فلترة الإعلانات">'+[{id:'الكل',label:'الكل'},...categories.filter(c=>c.id!=='الكل'),{id:'أخرى',label:'أخرى'}].map(c=>'<button class="filter '+(state.filter===c.id?'active':'')+'" data-filter="'+c.id+'">'+c.label+'</button>').join('')+'</div>';
const homeActivity=()=>'<div class="home-activity">'+notice()+'<button type="button" class="activity-link" data-go="listings">'+ic('grid')+'<span>إعلانات المعاينة: '+eligible().length+'</span>'+ic('arrow')+'</button></div>';
const home=()=>'<div class="shell home-v191 home-compact"><div class="market-search">'+search()+locationPicker()+searchChips()+'</div>'+homeActivity()+'<div class="market-stage"><div class="market-feature">'+hero()+'</div><div class="market-categories">'+catbar()+'</div><div class="market-actions"><button class="market-action buy" data-go="listings"><span>'+ic('search')+'</span><div><b>تصفّح السوق</b><small>اكتشف الإعلانات</small></div>'+ic('arrow')+'</button><button class="market-action merchant" data-new-store><span>'+ic('store')+'</span><div><b>افتح متجرك</b><small>نظّم منتجاتك</small></div>'+ic('arrow')+'</button><button class="market-action service" data-go="services"><span>'+ic('tools')+'</span><div><b>دليل الخدمات</b><small>اعثر على ما تحتاجه</small></div>'+ic('arrow')+'</button></div></div><div class="market-section">'+title('متاجر سوقك','تسوّق من المتاجر','stores')+shops(true)+'</div><a class="ct-entry ct-home-entry" href="./cloud-test.html"><span>'+ic('shield')+'</span><div><b>الاختبار المشترك لسوقك</b><small>تجربة منفصلة للحسابات والبيانات المشتركة</small></div>'+ic('arrow')+'</a><div class="market-section">'+title('أحدث الإعلانات','اكتشف اللي يناسبك','listings')+cards(eligible())+'</div></div>';
const searchChips=()=>{const chips=[['term',state.term?'البحث: '+state.term:''],['region',state.region!=='كل المناطق'?state.region:''],['city',state.city!=='كل المدن'?state.city:''],['category',state.filter!=='الكل'?state.filter:''],['price',state.priceMin!==''||state.priceMax!==''?'السعر: '+(state.priceMin||'0')+' – '+(state.priceMax||'بدون حد'):''],['mine',state.onlyMine?'إعلاناتي فقط':'']].filter(x=>x[1]);return chips.length?'<div class="active-search-chips" aria-label="الفلاتر المستخدمة">'+chips.map(([key,label])=>'<button type="button" data-clear-search="'+key+'" aria-label="إزالة '+esc(label)+'">'+esc(label)+' <span aria-hidden="true">×</span></button>').join('')+'<button class="clear-search-all" data-action="reset-local-search">مسح الفلاتر</button></div>':'';};
const discoveryPanel=(count)=>'<aside class="search-discovery"><div class="discovery-intro"><span class="discovery-icon">'+ic('search')+'</span><div><h3>'+(count===1?'تبي تشوف خيارات أكثر؟':'جرّب البحث بطريقة أخرى')+'</h3><p>استكشف أقسام سوقك أو عدّل نطاق البحث. هذه خيارات تصفح وليست نتائج مطابقة إضافية.</p></div></div><div class="discovery-categories">'+categories.filter(c=>['سيارات','إلكترونيات','المنزل'].includes(c.id)).map(c=>'<button type="button" data-discover="'+c.id+'">'+ic(c.icon)+'<span>'+c.label+'</span>'+ic('arrow')+'</button>').join('')+'</div><button class="more" data-action="reset-local-search">عرض جميع الإعلانات في هذه الدولة '+ic('arrow')+'</button></aside>';
const listings=()=>{const results=eligible().slice().sort((a,b)=>state.listingSort==='low'?a.price-b.price:state.listingSort==='high'?b.price-a.price:0),sparse=results.length<=1,elsewhere=state.term&&(state.region!=='كل المناطق'||state.city!=='كل المدن')?eligible(true).length-results.length:0;return '<div class="shell listings-page"><div class="screen-title"><h1>الإعلانات</h1><button data-go="home" aria-label="العودة">'+ic('back')+'</button></div>'+search()+locationPicker()+notice()+filters()+searchChips()+(elsewhere>0?'<div class="scope-hint"><div><b>نتائج مطابقة خارج الموقع المحدد</b><p>وجدنا '+elsewhere+' إعلان إضافي لنفس البحث في مناطق أخرى.</p></div><button class="more" data-action="expand-search-location">البحث في كل المناطق '+ic('arrow')+'</button></div>':'')+'<div class="feed-head"><h2>'+(state.term?'نتائج البحث عن: '+esc(state.term):state.region!=='كل المناطق'?'إعلانات '+esc(state.city!=='كل المدن'?state.city:state.region):'الإعلانات المتاحة')+'</h2><span class="subtext" role="status">'+results.length+' نتيجة</span><label class="sort-control">الترتيب <select id="listing-sort" aria-label="ترتيب الإعلانات">'+[['new','الأحدث في المعاينة'],['low','الأقل سعرًا'],['high','الأعلى سعرًا']].map(([v,t])=>'<option value="'+v+'" '+(state.listingSort===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label></div><div class="search-results-layout '+(sparse?'search-sparse':'')+'"><div class="search-primary">'+cards(results)+'</div>'+(sparse?discoveryPanel(results.length):'')+'</div></div>';};
const storePage=()=>'<div class="shell shops-page"><div class="screen-title"><h1>متاجر سوقك</h1><button data-go="home" aria-label="العودة">'+ic('back')+'</button></div>'+notice()+title('تسوّق من المتاجر','واجهة تجريبية')+shops()+'<div class="inline-alert">المتاجر هنا تصميم توضيحي. لا توجد شارات توثيق أو تقييمات أو عمليات بيع حقيقية في هذه المعاينة.</div><button class="cta" data-go="my-stores">متاجري '+ic('store')+'</button></div>';
const photoGallery=()=>state.photoUrls.length?'<div class="upload-previews" role="list" aria-label="صور الإعلان المختارة">'+state.photoUrls.map((p,i)=>'<div class="upload-thumb" role="listitem"><img src="'+p.url+'" alt="الصورة المختارة '+(i+1)+'"><span class="upload-count">'+(i===0?'رئيسية':i+1)+'</span>'+(i>0?'<button type="button" class="upload-main" aria-label="تعيين الصورة '+(i+1)+' رئيسية" data-photo-main="'+i+'">اجعلها رئيسية</button>':'')+'<div class="photo-order"><button type="button" data-photo-move="'+i+'" data-direction="-1" aria-label="تقديم الصورة" '+(i===0?'disabled':'')+'>‹</button><button type="button" data-photo-move="'+i+'" data-direction="1" aria-label="تأخير الصورة" '+(i===state.photoUrls.length-1?'disabled':'')+'>›</button></div><button type="button" aria-label="حذف الصورة '+(i+1)+'" data-photo-remove="'+i+'">×</button></div>').join('')+'</div>':'';
const post=()=>{
 const d=state.postDraft,step=state.postStep;
 const labels=['صور الإعلان','تفاصيل المنتج','المراجعة'];
 const progress='<div class="wizard-steps" role="navigation" aria-label="خطوات إضافة الإعلان">'+labels.map((label,i)=>'<button type="button" class="wizard-step '+(step===i+1?'active':step>i+1?'done':'')+'" data-post-step="'+(i+1)+'" aria-current="'+(step===i+1?'step':'false')+'"><span class="wizard-number">'+(i+1)+'</span><span>'+label+'</span></button>').join('')+'</div>';
 const photo='<section class="wizard-panel" data-wizard-panel="1"><div class="wizard-panel-header"><span class="wizard-icon">'+ic('camera')+'</span><div><h2>صور إعلانك</h2><p>الصورة الأولى هي الرئيسية، ويمكن ترتيب الصور بعد اختيارها</p></div></div><label class="upload wizard-upload" for="preview-images">'+ic('camera')+'<span id="upload-label">'+(state.photoUrls.length?'تم اختيار '+state.photoUrls.length+' صور':'أضف صور الإعلان')+'</span><small>اختيار محلي للمعاينة — حتى 10 صور</small></label><div class="photo-source"><button type="button" data-photo-picker="preview-images">اختيار عدة صور</button><button type="button" data-photo-picker="single-image">اختيار صورة واحدة</button><button type="button" data-photo-picker="capture-image">'+ic('camera')+' التقاط صورة</button></div><input id="preview-images" type="file" accept="image/*" multiple hidden><input id="single-image" type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/*" hidden><input id="capture-image" type="file" accept="image/*" capture="environment" hidden><p class="photo-help" id="photo-help" role="status">تختلف القائمة حسب جهازك: مكتبة الصور، الصور أو الملفات. إن لم تظهر الصور، افتح ملفاتي ثم الصور أو DCIM.</p><div id="upload-previews">'+photoGallery()+'</div></section>';
 const details='<section class="wizard-panel" data-wizard-panel="2"><div class="wizard-panel-header"><span class="wizard-icon">'+ic('grid')+'</span><div><h2>تفاصيل الإعلان</h2><p>معلومات واضحة تساعد المشتري يفهم عرضك بسهولة</p></div></div><div class="wizard-fields"><div class="field"><label for="post-title">عنوان الإعلان *</label><input id="post-title" name="title" required maxlength="100" placeholder="مثلاً: سيارة سيدان بحالة ممتازة" value="'+esc(d.title)+'"></div><div class="field"><label for="post-desc">الوصف</label><textarea id="post-desc" name="description" maxlength="2000" placeholder="الحالة والمواصفات وأهم التفاصيل">'+esc(d.description)+'</textarea></div><div class="field"><label for="post-price">السعر بالريال السعودي *</label><input id="post-price" name="price" required min="1" type="number" placeholder="مثلاً: 68,000" inputmode="numeric" value="'+esc(d.price)+'"></div><div class="field"><label for="post-cat">القسم</label><select id="post-cat" name="section">'+['سيارات','إلكترونيات','المنزل','خدمات','أخرى'].map(x=>'<option '+(d.section===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label for="post-region">المنطقة *</label><select id="post-region" name="region" required></select></div><div class="field"><label for="post-city">المدينة (اختياري)</label><select id="post-city" name="city"></select></div></div></section>';
 const review='<section class="wizard-panel" data-wizard-panel="3"><div class="wizard-panel-header"><span class="wizard-icon">'+ic('check')+'</span><div><h2>راجع إعلانك</h2><p>تأكد من التفاصيل قبل الإكمال</p></div></div><div class="wizard-summary"><div class="wizard-summary-photo">'+(state.photoUrls.length?'<img src="'+state.photoUrls[0].url+'" alt="الصورة الرئيسية للإعلان">':ic('camera'))+'</div><div class="wizard-summary-info"><strong>'+esc(d.title||'عنوان الإعلان')+'</strong><span class="wizard-summary-price">'+(d.price?formatted(d.price)+' ر.س':'السعر غير محدد')+'</span><small>'+esc(d.section)+' · '+esc(d.region)+(d.city?' · '+esc(d.city):'')+'</small></div></div><div class="review-thumbs">'+state.photoUrls.map((p,i)=>'<img src="'+esc(p.url)+'" alt="صورة الإعلان '+(i+1)+'">').join('')+'</div><div class="review-checks"><div><b>الصور</b><span>'+(state.photoUrls.length===1?'صورة واحدة':state.photoUrls.length+' صور')+'</span><button type="button" data-post-step="1" class="more">تعديل الصور</button></div><div><b>التفاصيل والموقع</b><span>'+esc(d.section)+' · '+esc(d.city||d.region)+'</span><button type="button" data-post-step="2" class="more">تعديل التفاصيل</button></div></div><p class="wizard-description">'+esc(d.description||'لا يوجد وصف إضافي')+'</p><div class="inline-alert">سيظهر إعلانك في البحث وإعلاناتي على هذا المتصفح. لا تُرسل الصور أو البيانات إلى خادم؛ لا تظهر في أجهزة أخرى.</div></section>';
 const panel=step===1?photo:step===2?details:review;
 const footer='<div class="wizard-actions">'+(step>1?'<button type="button" class="wizard-back" data-post-prev>'+ic('back')+' السابق</button>':'')+(step<3?'<button type="button" class="cta wizard-next" data-post-next>التالي '+ic('arrow')+'</button>':'<button type="button" class="cta wizard-preview" data-post-preview>إضافة الإعلان للتجربة '+ic('check')+'</button>')+'</div>';
 return '<div class="shell wizard-page"><div class="screen-title"><h1>إضافة إعلان</h1><button data-go="home" aria-label="العودة">'+ic('back')+'</button></div>'+notice()+'<div class="post-intro"><span class="post-eyebrow">إعلانك يبدأ هنا</span><h2>إعلانك في ثلاث خطوات</h2><p>صور، تفاصيل، ثم مراجعة.</p>'+(state.postStoreId?'<p class="post-store-context">سيضاف الإعلان إلى '+esc(state.localStores.find(x=>x.id===state.postStoreId)?.name||'متجرك')+'</p>':'')+'</div>'+progress+'<div class="wizard-card">'+panel+footer+'<div class="draft-footer"><small>تُحفظ المسودة على هذا المتصفح عند توفر التخزين.</small><button class="more" data-clear-draft>مسح المسودة</button></div></div></div>';
};
const account=()=>'<div class="shell account-page"><div class="screen-title"><h1>حسابي</h1><button data-go="home" aria-label="العودة">'+ic('back')+'</button></div>'+notice()+'<div class="profile account-hero"><span class="profile-avatar">'+ic('user')+'</span><div class="account-hero-content"><h2>مرحبًا بك في سوقك</h2><small>تتصفح الآن كزائر — سجّل الدخول لاستكمال حسابك</small><button class="account-login" data-go="auth">تسجيل الدخول '+ic('arrow')+'</button></div><div class="account-hero-art" aria-hidden="true"><span>'+ic('store')+'</span><span>'+ic('heart')+'</span><span>'+ic('grid')+'</span></div></div><div class="account-quick"><button data-go="my-ads" class="account-quick-card purple"><span>'+ic('grid')+'</span><b>إعلاناتي</b><small>'+items.filter(x=>x.local).length+' إعلان محلي</small></button><button data-go="my-stores" class="account-quick-card orange"><span>'+ic('store')+'</span><b>متاجري</b><small>'+state.localStores.length+' متجر تجريبي</small></button><button data-go="favorites" class="account-quick-card pink"><span>'+ic('heart')+'</span><b>المفضلة</b><small>'+state.favorites.size+' محفوظ محليًا</small></button><button data-go="messages" class="account-quick-card green"><span>'+ic('message')+'</span><b>رسائلي</b><small>المراسلة غير مفعلة</small></button></div><a class="ct-entry" href="./cloud-test.html"><span>'+ic('shield')+'</span><div><b>مختبر الحسابات المشتركة</b><small>اختبر الاتصال والإعلانات بين الأجهزة</small></div>'+ic('arrow')+'</a><div class="account-section-head">إدارة حسابك</div><div class="account-groups">'+[['نشاطي','إدارة عروضك ومحفوظاتك',[['grid','إعلاناتي','my-ads'],['store','إدارة متاجري','my-stores'],['heart','المفضلة','favorites']]],['التواصل','تابع رسائلك وآخر المستجدات',[['message','الرسائل','messages'],['bell','التنبيهات','notifications']]],['حسابك وسوقك','الإعدادات ومعلومات المنصة',[['settings','الإعدادات','demo'],['grid','تعرف على سوقك','welcome']]]].map(([heading,desc,rows])=>'<section class="account-group"><h3>'+heading+'</h3><p>'+desc+'</p><div class="profile-list">'+rows.map(([i,name,go])=>'<button class="profile-row" '+(go==='demo'?'data-action="demo"':'data-go="'+go+'"')+'><span class="item">'+ic(i)+name+'</span>'+ic('arrow')+'</button>').join('')+'</div></section>').join('')+'</div></div>';
const favorites=()=>{const all=items.filter(x=>state.favorites.has(x.id)),shown=all.filter(x=>state.favFilter==='الكل'||x.section===state.favFilter);return '<div class="shell favorites-page"><div class="screen-title"><h1>المفضلة</h1><button data-go="home" aria-label="العودة">'+ic('back')+'</button></div>'+notice()+'<div class="interior-hero fav-hero"><span class="interior-icon">'+ic('heart')+'</span><div><small>اختياراتك في مكان واحد</small><h2>محفوظاتك</h2><p>'+all.length+' إعلان محفوظ في المعاينة</p></div><button class="cta" data-go="listings">تصفح الإعلانات '+ic('arrow')+'</button></div><div class="filter-bar" aria-label="تصنيف المفضلة">'+['الكل',...new Set(all.map(x=>x.section))].map(c=>'<button data-fav-filter="'+esc(c)+'" aria-pressed="'+(c===state.favFilter)+'" class="'+(c===state.favFilter?'active':'')+'">'+esc(c)+'</button>').join('')+'</div><div class="section-head"><h2>الإعلانات المحفوظة</h2></div>'+(shown.length?cards(shown):'<div class="account-empty">'+ic('heart')+'<h2>لا توجد محفوظات هنا</h2><p>اضغط القلب على أي إعلان لتحفظه على هذا المتصفح.</p><button class="cta" data-go="listings">اكتشف الإعلانات</button></div>')+'</div>';};
const detailImages=x=>(Array.isArray(x.images)&&x.images.length?x.images:[x.image]).filter(p=>typeof p==='string'&&(x.local?p.startsWith('blob:'):/\.(svg|jpg)$/i.test(p)&&/^[a-z0-9.-]+$/i.test(p)));
const detail=()=>{
 const x=items.find(v=>v.id===state.item)||items[0];
 const imgs=detailImages(x),idx=Math.min(Math.max(0,state.detailIndex),Math.max(0,imgs.length-1));
 const main=imgs[idx]||x.image,saved=state.favorites.has(x.id);
 const thumb=imgs.map((p,i)=>'<button type="button" class="detail-thumb '+(i===idx?'active':'')+'" data-detail-image="'+i+'" aria-label="عرض صورة '+(i+1)+' للإعلان" aria-pressed="'+(i===idx)+'"><img src="'+esc(imageSrc(x,p))+'" alt="صورة '+(i+1)+' من الإعلان"></button>').join('');
 return '<div class="shell detail"><div class="screen-title"><h1>تفاصيل الإعلان</h1><button data-action="back-detail" aria-label="العودة">'+ic('back')+'</button></div>'+notice()+'<div class="detail-layout"><div class="detail-gallery"><div class="detail-hero"><img src="'+esc(imageSrc(x,main))+'" alt="'+esc(x.alt)+'" class="detail-primary-image" tabindex="0" role="button" aria-label="تكبير الصورة"><span class="detail-counter">'+(idx+1)+' / '+imgs.length+'</span>'+(imgs.length>1?'<button class="gallery-arrow gallery-prev" data-detail-image="'+((idx+imgs.length-1)%imgs.length)+'" aria-label="الصورة السابقة">‹</button><button class="gallery-arrow gallery-next" data-detail-image="'+((idx+1)%imgs.length)+'" aria-label="الصورة التالية">›</button>':'')+'</div><div class="detail-thumbnail-strip" role="group" aria-label="صور الإعلان">'+thumb+'</div></div><div class="detail-box"><span class="detail-category">'+esc(x.section)+'</span><h2>'+esc(x.title)+'</h2><div class="price">'+formatted(x.price)+' <small>ر.س</small></div><div class="detail-location">'+ic('pin')+'<span>'+esc(x.city||x.region||'')+'</span></div><p>'+esc(x.note)+'</p><div class="detail-actions"><button class="cta" data-go="messages">استكشف المراسلة '+ic('message')+'</button><button type="button" class="detail-fav '+(saved?'is-saved':'')+'" data-fav="'+x.id+'" aria-label="'+(saved?'إزالة من المفضلة':'حفظ في المفضلة')+'" aria-pressed="'+saved+'">'+ic('heart')+'<span>'+(saved?'محفوظ':'حفظ')+'</span></button></div><p class="detail-demo-note">المراسلة والإعلان الحقيقيان غير مفعّلين في هذه المعاينة.</p><div class="detail-share">'+(!x.local?'<button class="more" data-share-detail="'+x.id+'">مشاركة رابط المثال '+ic('arrow')+'</button>':'<small>هذا الإعلان محلي، لا يمكن مشاركته بين الأجهزة.</small>')+'</div><div class="detail-facts"><span>'+ic('camera')+' '+imgs.length+' صور</span><span>'+ic('shield')+' معاينة غير منشورة</span></div></div></div></div>';
};
const localStoreSetup=()=>{const d=state.storeDraft;return '<section class="wizard-card" aria-labelledby="store-setup-title"><h2 id="store-setup-title">جهّز متجرك للتجربة</h2><p>اختر اسمًا تجريبيًا ونشاطًا ووصفًا مختصرًا. تُحفظ المتاجر التجريبية محليًا على هذا المتصفح، ولا تُرسل لأي خادم.</p><form id="store-setup-form"><div class="wizard-fields"><div class="field"><label for="store-name">اسم المتجر *</label><input id="store-name" name="name" required minlength="3" maxlength="60" placeholder="مثلاً: متجر التقنية" value="'+esc(d.name)+'"></div><div class="field"><label for="store-section">نشاط المتجر</label><select id="store-section" name="section">'+['إلكترونيات','المنزل','سيارات','خدمات','أخرى'].map(x=>'<option '+(d.section===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label for="store-description">وصف المتجر (اختياري)</label><textarea id="store-description" name="description" maxlength="300" placeholder="عرّف بمتجرك باختصار">'+esc(d.description)+'</textarea></div></div><p id="store-setup-error" role="alert"></p><button type="submit" class="cta">حفظ ومعاينة متجري '+ic('arrow')+'</button></form>'+(state.storePreview?'<div class="store-heading" id="local-store-preview" tabindex="-1"><span class="store-badge">'+ic('store')+'</span><div><small>متجر شخصي تجريبي — غير منشور</small><h3>'+esc(d.name)+'</h3><p>'+esc(d.section)+'</p><p>'+esc(d.description||'لم تضف وصفًا بعد')+'</p><small>لا توجد منتجات مضافة إلى هذا المتجر.</small><button type="button" class="more" data-reset-store>مسح بيانات التجربة</button></div></div>':'')+'</section>';};
const createStore=()=>'<div class="shell create-store-page"><div class="screen-title"><h1>أنشئ متجرك</h1><button data-go="my-stores" aria-label="العودة">'+ic('back')+'</button></div><div class="store-start"><div><span class="ads-kicker">خطوتك الأولى نحو التجارة</span><h2>متجرك في سوقك</h2><p>تعرّف على طريقة عرض منتجاتك وتنظيم متجرك.</p><button class="cta" data-shop="tech" data-go="store">شاهد نموذج متجر '+ic('arrow')+'</button></div><img src="./assets/market-v163.svg" alt="واجهة متجر ومنتجات معروضة"></div><div class="store-benefits"><div>'+ic('grid')+'<b>اعرض منتجاتك</b><small>صفحة تجمع منتجاتك</small></div><div>'+ic('store')+'<b>هوية متجرك</b><small>واجهة خاصة بتجارتك</small></div><div>'+ic('user')+'<b>حساب واحد</b><small>تصفح وإدارة من مكان واحد</small></div></div><p class="inline-alert">فتح متجر فعلي غير متاح في المعاينة؛ يمكنك استكشاف نموذج متجر الآن.</p>'+localStoreSetup()+'</div>';
