const services=()=>{const visible=serviceTypes.filter(([n])=>!state.serviceTerm||normalizeSearch(n).includes(normalizeSearch(state.serviceTerm))),local=state.country==='السعودية'?items.filter(x=>x.local&&x.section==='خدمات'&&(state.region==='كل المناطق'||x.region===state.region)&&(state.city==='كل المدن'||x.city===state.city)&&(!state.serviceFilter||normalizeSearch([x.title,x.note].join(' ')).includes(normalizeSearch(state.serviceFilter)))&&(!state.serviceTerm||normalizeSearch([x.title,x.note].join(' ')).includes(normalizeSearch(state.serviceTerm)))):[];return '<div class="shell services-page"><div class="screen-title"><h1>دليل الخدمات</h1><button data-go="home" aria-label="العودة">'+ic('back')+'</button></div>'+notice()+'<div class="interior-hero services-hero"><span class="interior-icon">'+ic('tools')+'</span><div><small>خدمات سوقك</small><h2>كل الخدمات في مكان واحد</h2><p>اختر الخدمة والمنطقة لاستكشاف الدليل</p></div></div><form id="service-search" class="search service-search"><button type="submit" aria-label="بحث الخدمات">'+ic('search')+'</button><input name="q" placeholder="عن أي خدمة تبحث؟" value="'+esc(state.serviceTerm)+'"></form>'+locationPicker()+'<div class="section-head"><h2>أقسام الخدمات</h2></div><div class="service-grid">'+visible.map(([n,i],k)=>'<button class="service-tile tone-'+(k%4)+'" data-service="'+esc(n)+'" aria-pressed="'+(state.serviceFilter===n)+'"><span>'+ic(i)+'</span><b>'+esc(n)+'</b>'+ic('arrow')+'</button>').join('')+'</div><div class="account-empty service-result"><h2>'+esc(state.serviceFilter||'مقدمو الخدمات')+'</h2><p>'+(visible.length?'لا توجد بيانات مقدمي خدمات حقيقية في المعاينة.':'لا توجد أقسام مطابقة للبحث.')+'</p><button class="more" data-service-reset>عرض جميع الأقسام</button></div><div class="section-head"><h2>إعلانات الخدمات في المعاينة ('+local.length+')</h2></div>'+(local.length?cards(local):'<div class="service-empty-note">لا توجد إعلانات خدمات مطابقة في هذه الجلسة.</div>')+'<button class="cta" data-service-post>أضف إعلان خدمة '+ic('plus')+'</button></div>';};
