// Store only known fixture identifiers in the URL. Legacy #detail remains readable.
function routeFromHash(){
 const hash=location.hash.slice(1);
 if(hash.startsWith('my-store/')){const id=hash.slice(9);return state.localStores.some(x=>x.id===id)?{route:'my-store',localStoreId:id}:{route:'my-stores'};}
  if(hash.startsWith('store/')){const id=hash.slice(6);return shopData.some(x=>x.id===id)?{route:'store',storeId:id}:{route:'stores'};}
 if(hash==='detail')return {route:'detail',item:items[0].id};
 if(hash.startsWith('detail/')){
  const id=hash.slice(7);
  return items.some(x=>x.id===id)?{route:'detail',item:id}:{route:'listings'};
 }
 return {route:routes.has(hash)?hash:'home'};
}
function syncRoute(initial=false){
 const next=routeFromHash();
 const changed=state.route!==next.route||(next.route==='my-store'&&state.localStoreId!==next.localStoreId)||(next.route==='detail'&&state.item!==next.item)||(next.route==='store'&&next.storeId&&state.storeId!==next.storeId);
 state.route=next.route;if(next.localStoreId)state.localStoreId=next.localStoreId;if(next.storeId)state.storeId=next.storeId;
 if(next.route==='detail'){if(state.item!==next.item)state.detailIndex=0;state.item=next.item;}
 if(initial||changed)render();
}
let storeTimer=0;
function shiftStore(delta){const shop=shopData.find(x=>x.id===state.storeId)||shopData[0],n=storeSlides(shop).length;state.storeSlide=(state.storeSlide+delta+n)%n;const el=$('#store-carousel');if(el)el.innerHTML=storeBanner(shop);scheduleStore()}
