const localMedia=new Map();let workspaceDB=null,workspaceReady=false,workspaceFailed=false,workspaceQueue=Promise.resolve();
function rememberMedia(blob){const url=URL.createObjectURL(blob);localMedia.set(url,blob);return url}
function releaseMedia(url){localMedia.delete(url);URL.revokeObjectURL(url)}
function openWorkspace(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('IndexedDB unavailable'));return}const req=indexedDB.open('sooqak-preview-workspace',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('blocked'))})}
function workspaceRead(){return new Promise((resolve,reject)=>{const tx=workspaceDB.transaction('workspace','readonly'),q=tx.objectStore('workspace').get('current');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function workspaceWrite(data){return new Promise((resolve,reject)=>{const tx=workspaceDB.transaction('workspace','readwrite');tx.objectStore('workspace').put(data,'current');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('aborted'))})}
function snapshotWorkspace(){const blob=url=>localMedia.get(url)||null;return {schema:1,ads:items.filter(x=>x.local).map(x=>({...x,image:undefined,images:x.images.map(blob).filter(Boolean)})),stores:state.localStores.map(x=>({...x,ads:[...x.ads],logo:blob(x.logo),cover:blob(x.cover)})),draft:{...state.postDraft},draftPhotos:state.photoUrls.map(x=>({name:x.name,blob:blob(x.url)})).filter(x=>x.blob),step:state.postStep,postStoreId:state.postStoreId,storeDraft:{...state.storeDraft},favorites:[...state.favorites],activity:state.activity.map(x=>({...x})),nextDemoId,nextStoreId}}
function restoreWorkspace(d){if(!d||d.schema!==1)return;const validBlob=b=>b instanceof Blob&&b.size>0&&b.size<=8*1024*1024&&['image/jpeg','image/png','image/webp','image/gif',''].includes(b.type);const validId=(s,p)=>typeof s==='string'&&new RegExp('^'+p+'[0-9]+$').test(s);for(const x of (Array.isArray(d.ads)?d.ads:[]).slice(0,5)){if(!validId(x.id,'local-')||items.some(v=>v.id===x.id)||!Array.isArray(x.images))continue;const urls=x.images.filter(validBlob).slice(0,10).map(rememberMedia);if(!urls.length)continue;items.push({id:x.id,title:String(x.title||'').slice(0,100),price:Number(x.price)||0,city:String(x.city||''),region:String(x.region||''),section:String(x.section||'أخرى'),image:urls[0],images:urls,alt:'صورة إعلانك التجريبي',note:String(x.note||'').slice(0,2000),local:true})}state.localStores=(Array.isArray(d.stores)?d.stores:[]).slice(0,10).filter(x=>validId(x.id,'demo-store-')).map(x=>({id:x.id,name:String(x.name||'').slice(0,60),section:String(x.section||'أخرى'),description:String(x.description||'').slice(0,300),ads:(Array.isArray(x.ads)?x.ads:[]).filter(id=>items.some(v=>v.local&&v.id===id)),logo:validBlob(x.logo)?rememberMedia(x.logo):'',cover:validBlob(x.cover)?rememberMedia(x.cover):''}));if(d.draft&&typeof d.draft==='object'){for(const k of Object.keys(state.postDraft))if(typeof d.draft[k]==='string')state.postDraft[k]=d.draft[k].slice(0,k==='description'?2000:100)}state.photoUrls=(Array.isArray(d.draftPhotos)?d.draftPhotos:[]).slice(0,10).filter(x=>validBlob(x.blob)).map(x=>({name:String(x.name||''),url:rememberMedia(x.blob)}));state.postStep=state.photoUrls.length&&[1,2,3].includes(d.step)?d.step:1;state.postStoreId=state.localStores.some(x=>x.id===d.postStoreId)?d.postStoreId:'';if(d.storeDraft&&typeof d.storeDraft==='object')for(const k of Object.keys(state.storeDraft))if(typeof d.storeDraft[k]==='string')state.storeDraft[k]=d.storeDraft[k].slice(0,300);state.favorites=new Set((Array.isArray(d.favorites)?d.favorites:[]).filter(id=>items.some(x=>x.id===id)));state.activity=(Array.isArray(d.activity)?d.activity:[]).slice(0,30).filter(x=>typeof x.text==='string'&&typeof x.time==='string');nextDemoId=Math.max(Number.isSafeInteger(d.nextDemoId)?d.nextDemoId:0,0,...items.filter(x=>x.local).map(x=>Number(x.id.slice(6))||0));nextStoreId=Math.max(Number.isSafeInteger(d.nextStoreId)?d.nextStoreId:0,0,...state.localStores.map(x=>Number(x.id.slice(11))||0))}
function saveWorkspace(){if(!workspaceReady||workspaceFailed)return;const data=snapshotWorkspace();workspaceQueue=workspaceQueue.catch(()=>{}).then(()=>workspaceWrite(data)).catch(()=>{workspaceFailed=true;toast('تعذر الحفظ المحلي؛ قد تفقد التغييرات عند إغلاق الصفحة.');const el=$('#workspace-status');if(el)el.textContent='الحفظ المحلي غير متاح'})}
const workspaceStatus=()=>workspaceFailed?'الحفظ المحلي غير متاح':workspaceReady?'حفظ على هذا المتصفح فقط':'جارٍ تجهيز الحفظ المحلي';

