 const targetStore=state.localStores.find(x=>x.id===state.postStoreId);state.postStoreId='';if(targetStore){targetStore.ads.push(id);state.localStoreId=targetStore.id;go('my-store');toast('تم إنشاء الإعلان وإضافته إلى متجرك');return}go('my-ads');dialog('أضيف إعلانك للتجربة','تقدر تشوف إعلانك في إعلاناتي وتبحث عنه الآن. الحفظ محلي في هذا المتصفح فقط.');
