function validLocalImage(f){return f.size>0&&f.size<=8*1024*1024&&(['image/jpeg','image/png','image/webp','image/gif'].includes(f.type)||(!f.type&&/\.(jpe?g|png|webp|gif)$/i.test(f.name||'')))}
