 if(e.target.id==='post-region'){state.postDraft.region=e.target.value;state.postDraft.city='';const city=$('#post-city');if(city){const options=(locationMap['السعودية'][e.target.value]||[]);city.replaceChildren(new Option('المدينة اختيارية',''),...options.map(x=>new Option(x,x)));}return}if(e.target.id==='post-city'){state.postDraft.city=e.target.value;return}if(e.target.id==='post-cat'){state.postDraft.section=e.target.value;return}
  if(['preview-images','single-image','capture-image'].includes(e.target.id)){const files=Array.from(e.target.files||[]);if(files.length+state.photoUrls.length>10){toast('الحد الأقصى 10 صور');e.target.value='';return}if(files.some(f=>!validLocalImage(f))){toast('اختر صور JPG أو PNG أو WEBP أو GIF، حتى 8 ميجابايت للصورة');e.target.value='';return}for(const f of files)state.photoUrls.push({url:rememberMedia(f),name:f.name});const help=$('#photo-help');if(help&&files.length)help.textContent='تم اختيار '+files.length+' صورة. يمكنك اختيار المزيد أو ترتيب الصور.';const frame=$('#upload-previews');if(frame)frame.innerHTML=photoGallery();const label=$('#upload-label');if(label)label.textContent=state.photoUrls.length?'تم اختيار '+state.photoUrls.length+' صور — يمكنك إضافة المزيد':'أضف صور الإعلان';e.target.value='';return}
