document.addEventListener('keydown',e=>{const modal=$('.dialog-card');if(modal&&e.key==='Escape'){e.preventDefault();const image=!!$('.image-dialog');action('close');if(image)$('.detail-primary-image')?.focus();else $('.search-filter-btn')?.focus();return}if(modal&&e.key==='Tab'&&modal.querySelectorAll){const controls=Array.from(modal.querySelectorAll('button:not([disabled]),input:not([disabled]):not([hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]'));if(controls.length){const first=controls[0],last=controls.at(-1);if(e.shiftKey&&(document.activeElement===first||!modal.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){e.preventDefault();first.focus()}}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.detail-primary-image')){e.preventDefault();openDetailImage(e.target)}});
